OUT = "/workspace/outputs/images"
LOG = "/workspace/tmp/gen_log.txt"

def log(msg):
    with open(LOG, "a", encoding="utf-8") as f:
        f.write(msg + "\n")

only = [int(x) for x in sys.argv[1:]] if len(sys.argv) > 1 else None
for n in (only or sorted(PAGES)):
    out = f"{OUT}/page_{n:02d}.png"
    if os.path.exists(out) and os.path.getsize(out) > 50000:
        log(f"page {n}: skip (exists)")
        continue
    meta = PAGES[n]
    full = STYLE + "。\n页面主题：" + meta["title"] + "。\n画面中需要准确呈现的文字：" + meta["text"].replace("\n", "；") + "。\n" + meta["prompt"]
    ok = False
    for attempt in range(1, 4):
        try:
            r = subprocess.run(["python", "/opt/eval-adapter/ecnu_tools.py", "image",
                                "--text", full, "--output", out],
                               capture_output=True, text=True, timeout=600)
            if r.returncode == 0 and os.path.exists(out) and os.path.getsize(out) > 50000:
                log(f"page {n}: OK attempt {attempt} size={os.path.getsize(out)}")
                ok = True
                break
            log(f"page {n}: attempt {attempt} rc={r.returncode} out={r.stdout[-300:]} err={r.stderr[-300:]}")
        except Exception as e:
            log(f"page {n}: attempt {attempt} EXC {e}")
        time.sleep(5)
    if not ok:
        log(f"page {n}: FAILED")
print("done")
